ssize_t macvtap_get_and_process_skb(struct macvtap_queue *q,
                                    struct msghdr *m,
                                    const struct iovec *iv,
                                    unsigned long total_len,
                                    size_t count,
                                    int noblock) {
    struct sk_buff *skb;
    ssize_t ret = -EINVAL;

    if (!q || !m || !iv || total_len == 0 || count == 0)
        return ret;

    skb = alloc_skb(total_len + ETH_HLEN, GFP_KERNEL);
    if (!skb)
        return -ENOMEM;

    if (process_virtio_header(q, skb)) {
        kfree_skb(skb);
        return -EINVAL;
    }

    if (copy_from_iter(skb->data, total_len, m->msg_iter)) {
        kfree_skb(skb);
        return -EFAULT;
    }

    skb->len = total_len;
    skb->data_len = total_len;
    skb_set_tail_pointer(skb, total_len);

    if (handle_zero_copy(skb, iv, count)) {
        kfree_skb(skb);
        return -EFAULT;
    }

    if (q->vlan) {
        if (transmit_skb(skb, q->vlan)) {
            kfree_skb(skb);
            return -EIO;
        }
    }

    ret = total_len;
    return ret;
}

ssize_t macvtap_get_data(struct macvtap_queue *q, struct msghdr *m,
                         const struct iovec *iv, unsigned long total_len,
                         size_t count, int noblock) {
    struct sk_buff *skb;
    int err;

    if (!q || !m || !iv || total_len == 0 || count == 0)
        return -EINVAL;

    skb = alloc_skb(total_len, GFP_KERNEL);
    if (!skb)
        return -ENOMEM;

    skb_put(skb, total_len);

    err = skb_copy_datagram_from_iovec(skb, 0, iv, 0, total_len);
    if (err) {
        kfree_skb(skb);
        return err;
    }

    if (q->vlan_id) {
        struct vlan_ethhdr *veth;
        veth = skb_push(skb, VLAN_HLEN);
        veth->h_vlan_proto = htons(ETH_P_8021Q);
        veth->h_vlan_TCI = htons(q->vlan_id);
        skb->protocol = htons(ETH_P_8021Q);
    }

    skb->dev = q->dev;
    skb->priority = 0;

    err = dev_queue_xmit(skb);
    if (err < 0) {
        return err;
    }

    return total_len;
}

ssize_t macvtap_get_user(struct macvtap_queue *q, struct msghdr *m,
                         const struct iovec *iv, unsigned long total_len,
                         size_t count, int noblock)
{
    struct sk_buff *skb;
    int err;

    if (!q || !m || !iv || total_len == 0 || count == 0)
        return -EINVAL;

    skb = alloc_skb(0, GFP_KERNEL);
    if (!skb)
        return -ENOMEM;

    skb->dev = q->dev;
    skb->priority = 0;

    err = skb_zerocopy(skb, iv, count, total_len);
    if (err < 0)
        goto free_skb;

    if (q->vnet_hdr) {
        struct virtio_net_hdr *hdr = skb_put(skb, sizeof(*hdr));
        memset(hdr, 0, sizeof(*hdr));
    }

    skb_reset_mac_header(skb);
    skb_set_network_header(skb, skb_headroom(skb));

    if (q->vlan) {
        skb->vlan_tci = q->vlan;
        __vlan_hwaccel_put_tag(skb, htons(ETH_P_8021Q), q->vlan);
    }

    netif_receive_skb(skb);
    return total_len;

free_skb:
    kfree_skb(skb);
    return err;
}

ssize_t macvtap_get_user(struct macvtap_queue *q, struct msghdr *m,
                         const struct iovec *iv, unsigned long total_len,
                         size_t count, int noblock) {
    struct sk_buff *skb;
    ssize_t ret;
    size_t len = total_len;
    size_t copy = len;
    size_t i = 0;
    struct virtio_net_hdr virt_hdr;
    int err;

    skb = alloc_skb(len + VLAN_HLEN, GFP_KERNEL);
    if (!skb)
        return -ENOMEM;

    skb->dev = q->vdev->priv;

    if (q->vdev->config->get_config(q->vdev, &virt_hdr, sizeof(virt_hdr)) == 0 &&
        virt_hdr.hdr_size > 0) {
        len -= virt_hdr.hdr_size;
        copy -= virt_hdr.hdr_size;
    }

    if (copy) {
        for (; i < count && copy; i++) {
            struct iovec *iov = (struct iovec *)&iv[i];
            size_t size = min(iov->iov_len, copy);
            if (!iov->iov_len)
                continue;
            err = skb_add_data_from_iter(skb, iov->iov_base, size);
            if (err) {
                ret = err;
                goto error;
            }
            copy -= size;
        }
    }

    if (copy)
        ret = -EINVAL;
    else
        ret = len;

    if (ret < 0)
        goto error;

    skb->len = len;
    skb->data_len = len;
    skb->truesize += len;
    atomic_add(len, &skb->truesize);

    if (q->vlan) {
        skb = __skb_vlan_pop(skb, htons(ETH_P_8021Q), NULL);
        if (!skb)
            ret = -ENOMEM;
    }

    if (ret >= 0)
        dev_queue_xmit(skb);

    return ret;

error:
    kfree_skb(skb);
    return ret;
}

ssize_t macvtap_get_user(struct macvtap_queue *q, struct msghdr *m,
                         const struct iovec *iv, unsigned long total_len,
                         size_t count, int noblock) {
    struct sk_buff *skb;
    struct virtio_net_hdr vnet_hdr;
    int err = 0;
    ssize_t len = 0;
    unsigned int vnet_hdr_len = 0;
    bool zcopy = false;

    if (total_len == 0)
        return 0;

    if (q->vnet_hdr) {
        vnet_hdr_len = sizeof(vnet_hdr);
        if (copy_from_user(&vnet_hdr, m->msg_control, vnet_hdr_len))
            return -EFAULT;
    }

    skb = alloc_skb(0, GFP_KERNEL);
    if (!skb)
        return -ENOMEM;

    skb->ip_summed = vnet_hdr.csum ? CHECKSUM_NONE : CHECKSUM_UNNECESSARY;
    skb_set_network_header(skb, 0);

    if (count) {
        len = skb_copy_datagram_from_iovec(skb, 0, iv, 0, total_len);
        if (len < 0) {
            kfree_skb(skb);
            return len;
        }
    }

    if (zcopy) {
        skb_zcopy_clear(skb);
    }

    if (q->vlan) {
        skb->vlan_tci = htons(q->vlan);
    }

    skb->protocol = eth_type_trans(skb, q->dev);
    skb->dev = q->dev;
    skb->priority = 1;

    netif_receive_skb(skb);

    return total_len;
}
